27	const SuspenseNotifier: FC<{ onLoadingChange?: (loading: boolean) => void }> = ({
28	  onLoadingChange,
29	}) => {
30	  useEffect(() => {
31	    onLoadingChange?.(false);
32	    return () => {
33	      onLoadingChange?.(true);
34	    };
35	  }, [onLoadingChange]);
36	  return null;
