'use client';

import { useMemo } from 'react';
import * as THREE from 'three';

// Fixed wall dimensions in meters — wall never changes size
export const WALL_WIDTH = 10.0; // 10m total wall width
export const WALL_HEIGHT = 3.7; // 3.7m total wall height
export const WALL_THICKNESS = 0.2; // 20cm wall thickness
export const WALL_CENTER_Z = -0.05;

/** A generic rectangular hole in the wall (e.g. window) */
export interface WallHole {
  centerX: number; // center X relative to wall center
  bottomY: number; // bottom Y in wall-local coords (wallBottom = -WALL_HEIGHT/2)
  width: number;
  height: number;
}

/** MeshStandardMaterial props used for wall surface rendering */
export interface WallMaterialProps {
  color?: THREE.ColorRepresentation;
  map?: THREE.Texture;
  normalMap?: THREE.Texture;
  roughnessMap?: THREE.Texture;
  aoMap?: THREE.Texture;
  aoMapIntensity?: number;
  bumpMap?: THREE.Texture;
  bumpScale?: number;
  roughness?: number;
  metalness?: number;
  normalScale?: THREE.Vector2;
  envMapIntensity?: number;
}

interface ParametricWallProps {
  // Door opening dimensions (includes frame) — only the hole changes
  openingWidth: number;
  openingHeight: number;
  wallColor?: string;

