85	    if (!mesh) return;
86	    const geom = mesh.geometry as THREE.BufferGeometry;
87	    const uv = geom.attributes.uv;
88	    if (uv && !geom.attributes.uv2) {
89	      geom.setAttribute('uv2', uv.clone());
90	    }
91	  }, [ref]);
