'use client';

import { useTexture } from '@react-three/drei';
import { useThree } from '@react-three/fiber';
import { useEffect, useMemo, useRef } from 'react';
import * as THREE from 'three';
import {
  clampDoorHeightMm,
  clampDoorWidthMm,
} from '../../const';
import {
  useDoorHeight,
  useDoorLayout,
  useDoorLeftGlassWidth,
  useDoorRightGlassWidth,
  useSceneExteriorWallColor,
  useSceneExteriorWallFinish,
  useSceneInteriorWallColor,
  useDoorUpperGlassHeight,
  useDoorWidth,
} from '../../store';
import { sceneWallFinishes } from '../../const';
import { useFacadeTextures } from '../../hooks/useFacadeTextures';
import { useWallSurfaceMaterial } from '../../hooks/useWallSurfaceMaterial';
import {
  ParametricWall,
  WALL_CENTER_Z,
  WALL_HEIGHT,
  WALL_THICKNESS,
  WALL_WIDTH,
  WallHole,
  WallMaterialProps,
} from './ParametricWall';
import {
  ParametricWindow,
  WINDOW_HEIGHT,
  WINDOW_SILL_HEIGHT,
  WINDOW_WIDTH,
} from './ParametricWindow';

// Door frame constants (must match ParametricDoor)
const FRAME_PROFILE_WIDTH = 0.066;
const FRAME_PROFILE_WIDTH_BOTTOM = 0.03;

// House constants
const HOUSE_DEPTH = 10.0; // meters
const ROOF_THICKNESS = 0.15;
const ROOF_COLOR = '#555555';
const WALL_COLOR = '#e8e0d4';
const FOUNDATION_HEIGHT = 0.36;
const FOUNDATION_TOP_CLEARANCE = 0.005;
const INTER_FLOOR_SLAB_THICKNESS = 0.16;
const INTER_FLOOR_SLAB_INSET = 0.08;
const INTERIOR_FLOOR_SURFACE_OFFSET = 0.01;
const STEP_COUNT = 2;
const STEP_DEPTH = 1.0;
const FOUNDATION_COLOR = '#8e877f';
const DARK_CONCRETE_COLOR = '#6f6a64';
const STAIR_CONCRETE_COLOR = '#e6ddd0';
const LOWER_STEP_WIDTH = 5.2;
const UPPER_STEP_WIDTH = 6.4;
const UPPER_STEP_DEPTH = 1.44;

// Fascia
const FASCIA_HEIGHT = 0.04;
const FASCIA_DEPTH = 0.02;
const FASCIA_COLOR = '#333333';

// Window placement
const WINDOW_CENTER_X = -3.0; // left of door, good spacing on wider wall
const UPPER_WINDOW_CENTER_X = 3.0;

// Convert mm to meters
const mmToM = (mm: number) => mm / 1000;
const FLOOR_Y = -WALL_HEIGHT / 2;
const CEILING_Y = WALL_HEIGHT / 2;
const FRONT_WALL_BACK_FACE_Z = WALL_CENTER_Z - WALL_THICKNESS / 2;

/**
 * Helper: copies uv → uv2 so aoMap works on box geometries.
 */
function useUv2(ref: React.RefObject<THREE.Mesh | null>) {
  useEffect(() => {
    const mesh = ref.current;
    if (!mesh) return;
    const geom = mesh.geometry as THREE.BufferGeometry;
    const uv = geom.attributes.uv;
    if (uv && !geom.attributes.uv2) {
      geom.setAttribute('uv2', uv.clone());
    }
  }, [ref]);
}

function useInteriorFloorMaterial(): WallMaterialProps {
  const { gl } = useThree();
  const sourceTextures = useTexture({
    map: '/textures/floor/Zebrano_Rift_Sawn_Natural_Finish_Veneer_Wood_basecolor_2K.png',
    normalMap:
      '/textures/floor/Zebrano_Rift_Sawn_Natural_Finish_Veneer_Wood_normal_2K.png',
    roughnessMap:
      '/textures/floor/Zebrano_Rift_Sawn_Natural_Finish_Veneer_Wood_roughness_2K.png',
  });

  const textures = useMemo(() => {
    const anisotropy = Math.min(16, gl.capabilities.getMaxAnisotropy());
    const map = sourceTextures.map.clone();
    const normalMap = sourceTextures.normalMap.clone();
    const roughnessMap = sourceTextures.roughnessMap.clone();

    [map, normalMap, roughnessMap].forEach((texture, index) => {
      texture.wrapS = THREE.RepeatWrapping;
      texture.wrapT = THREE.RepeatWrapping;
      texture.repeat.set(2.8, 5.6);
      texture.magFilter = THREE.LinearFilter;
      texture.minFilter = THREE.LinearMipmapLinearFilter;
      texture.anisotropy = anisotropy;
      texture.needsUpdate = true;

      if (index === 0) {
        texture.colorSpace = THREE.SRGBColorSpace;
      }
    });

    return { map, normalMap, roughnessMap };
  }, [gl, sourceTextures]);

  useEffect(() => {
    return () => {
      textures.map?.dispose();
      textures.normalMap?.dispose();
      textures.roughnessMap?.dispose();
    };
  }, [textures]);

  return useMemo(() => {
    return {
      color: '#ffffff',
      map: textures.map ?? undefined,
      normalMap: textures.normalMap ?? undefined,
      roughnessMap: textures.roughnessMap ?? undefined,
      normalScale: new THREE.Vector2(0.16, 0.16),
      roughness: 0.9,
      metalness: 0.02,
      envMapIntensity: 0.03,
    };
  }, [textures]);
}

interface HouseFloorShellProps {
  elevationY: number;
  frontWallOpeningWidth: number;
  frontWallOpeningHeight: number;
  showFrontDoorOpening?: boolean;
  windowCentersX: number[];
  windowHoles: WallHole[];
  frontExteriorTextureMaps: Partial<WallMaterialProps>;
  frontInteriorTextureMaps: Partial<WallMaterialProps>;
  sideExteriorTextureMaps: Partial<WallMaterialProps>;
  sideInteriorTextureMaps: Partial<WallMaterialProps>;
  backExteriorTextureMaps: Partial<WallMaterialProps>;
  backInteriorTextureMaps: Partial<WallMaterialProps>;
}

const HouseFloorShell: React.FC<HouseFloorShellProps> = ({
  elevationY,
  frontWallOpeningWidth,
  frontWallOpeningHeight,
  showFrontDoorOpening = true,
  windowCentersX,
  windowHoles,
  frontExteriorTextureMaps,
  frontInteriorTextureMaps,
  sideExteriorTextureMaps,
  sideInteriorTextureMaps,
  backExteriorTextureMaps,
  backInteriorTextureMaps,
}) => {
  const leftWallRef = useRef<THREE.Mesh>(null);
  const rightWallRef = useRef<THREE.Mesh>(null);
  const backWallRef = useRef<THREE.Mesh>(null);

  useUv2(leftWallRef);
  useUv2(rightWallRef);
  useUv2(backWallRef);

  const backWallZ = FRONT_WALL_BACK_FACE_Z - HOUSE_DEPTH;
  const houseFrontZ = FRONT_WALL_BACK_FACE_Z;
  const houseBackZ = backWallZ - WALL_THICKNESS / 2;
  const sideWallDepth = houseFrontZ - houseBackZ;
  const sideWallCenterZ = (houseFrontZ + houseBackZ) / 2;
  const sideWallX = WALL_WIDTH / 2 + WALL_THICKNESS / 2;
  const windowCenterY = FLOOR_Y + WINDOW_SILL_HEIGHT + WINDOW_HEIGHT / 2;

  return (
    <group position={[0, elevationY, 0]}>
      <ParametricWall
        openingWidth={frontWallOpeningWidth}
        openingHeight={frontWallOpeningHeight}
        showDoorOpening={showFrontDoorOpening}
        wallColor={WALL_COLOR}
        position={[0, 0, WALL_CENTER_Z]}
        width={WALL_WIDTH + 2 * WALL_THICKNESS}
        additionalHoles={windowHoles}
        exteriorTextureMaps={frontExteriorTextureMaps}
        interiorTextureMaps={frontInteriorTextureMaps}
      />

      {windowCentersX.map((centerX) => (
        <ParametricWindow
          key={centerX}
          position={[centerX, windowCenterY, WALL_CENTER_Z]}
        />
      ))}

      <mesh
        ref={leftWallRef}
        position={[-sideWallX, 0, sideWallCenterZ]}
        castShadow
        receiveShadow
      >
        <boxGeometry args={[WALL_THICKNESS, WALL_HEIGHT, sideWallDepth]} />
        <meshStandardMaterial attach="material-0" {...sideInteriorTextureMaps} />
        <meshStandardMaterial attach="material-1" {...sideExteriorTextureMaps} />
        <meshStandardMaterial attach="material-2" {...sideExteriorTextureMaps} />
        <meshStandardMaterial attach="material-3" {...sideExteriorTextureMaps} />
        <meshStandardMaterial attach="material-4" {...sideExteriorTextureMaps} />
        <meshStandardMaterial attach="material-5" {...sideExteriorTextureMaps} />
      </mesh>

      <mesh
        ref={rightWallRef}
        position={[sideWallX, 0, sideWallCenterZ]}
        castShadow
        receiveShadow
      >
        <boxGeometry args={[WALL_THICKNESS, WALL_HEIGHT, sideWallDepth]} />
        <meshStandardMaterial attach="material-0" {...sideExteriorTextureMaps} />
        <meshStandardMaterial attach="material-1" {...sideInteriorTextureMaps} />
        <meshStandardMaterial attach="material-2" {...sideExteriorTextureMaps} />
        <meshStandardMaterial attach="material-3" {...sideExteriorTextureMaps} />
        <meshStandardMaterial attach="material-4" {...sideExteriorTextureMaps} />
        <meshStandardMaterial attach="material-5" {...sideExteriorTextureMaps} />
      </mesh>

      <mesh
        ref={backWallRef}
        position={[0, 0, backWallZ]}
        castShadow
        receiveShadow
      >
        <boxGeometry
          args={[WALL_WIDTH + 2 * WALL_THICKNESS, WALL_HEIGHT, WALL_THICKNESS]}
        />
        <meshStandardMaterial attach="material-0" {...backExteriorTextureMaps} />
        <meshStandardMaterial attach="material-1" {...backExteriorTextureMaps} />
        <meshStandardMaterial attach="material-2" {...backExteriorTextureMaps} />
        <meshStandardMaterial attach="material-3" {...backExteriorTextureMaps} />
        <meshStandardMaterial attach="material-4" {...backInteriorTextureMaps} />
        <meshStandardMaterial attach="material-5" {...backExteriorTextureMaps} />
      </mesh>
    </group>
  );
};

interface ConcreteBoxProps {
  materialProps: Partial<WallMaterialProps>;
  position: [number, number, number];
  size: [number, number, number];
}

const ConcreteBox: React.FC<ConcreteBoxProps> = ({
  materialProps,
  position,
  size,
}) => {
  const ref = useRef<THREE.Mesh>(null);

  useUv2(ref);

  return (
    <mesh ref={ref} position={position} castShadow receiveShadow>
      <boxGeometry args={size} />
      <meshStandardMaterial {...materialProps} />
    </mesh>
  );
};

interface ParametricHouseProps {
  proposal?: Proposal;
}

export const ParametricHouse: React.FC<ParametricHouseProps> = ({ proposal }) => {
  // Read door dimensions to compute front wall opening
  const selectedDoorWidthMm = useDoorWidth();
  const selectedDoorHeightMm = useDoorHeight();
  const selectedTopGlassHeightMm = useDoorUpperGlassHeight();
  const selectedLeftGlassWidthMm = useDoorLeftGlassWidth();
  const selectedRightGlassWidthMm = useDoorRightGlassWidth();
  const selectedLayout = useDoorLayout();
  const selectedExteriorFinish = useSceneExteriorWallFinish();
  const selectedExteriorColor = useSceneExteriorWallColor();
  const selectedInteriorColor = useSceneInteriorWallColor();
  const doorWidth = mmToM(
    clampDoorWidthMm(proposal?.doorWidth ?? selectedDoorWidthMm),
  );
  const doorHeight = mmToM(
    clampDoorHeightMm(proposal?.doorHeight ?? selectedDoorHeightMm),
  );

  const topGlassHeight = mmToM(
    proposal?.topGlassHeight ?? selectedTopGlassHeightMm,
  );
  const leftGlassWidth = mmToM(
    proposal?.leftGlassWidth ?? selectedLeftGlassWidthMm,
  );
  const rightGlassWidth = mmToM(
    proposal?.rightGlassWidth ?? selectedRightGlassWidthMm,
  );

  const layout = proposal?.layout ?? selectedLayout;
  const exteriorFinish = proposal?.sceneExteriorWallFinish ?? selectedExteriorFinish;
  const exteriorColor = proposal?.sceneExteriorWallColor ?? selectedExteriorColor;
  const interiorFinish = sceneWallFinishes[0];
  const interiorColor = proposal?.sceneInteriorWallColor ?? selectedInteriorColor;
  const hasTopGlass = layout?.id?.includes('top') ?? false;
  const hasLeftGlass = layout?.id?.includes('left') ?? false;
  const hasRightGlass = layout?.id?.includes('right') ?? false;

  const actualTopGlassHeight = hasTopGlass ? topGlassHeight : 0;
  const actualLeftGlassWidth = hasLeftGlass ? leftGlassWidth : 0;
  const actualRightGlassWidth = hasRightGlass ? rightGlassWidth : 0;

  // Door opening dimensions (same logic as ParametricDoor)
  const doorOpeningWidth =
    doorWidth +
    actualLeftGlassWidth +
    actualRightGlassWidth +
    FRAME_PROFILE_WIDTH * 2;

  let topOffset = FRAME_PROFILE_WIDTH;
  if (hasTopGlass) topOffset += actualTopGlassHeight;
  const doorOpeningHeight = doorHeight + FRAME_PROFILE_WIDTH_BOTTOM + topOffset;

  // Front wall uses ExtrudeGeometry while side/back walls use BoxGeometry,
  // so each surface family needs its own texture repeat scale.
  const frontExteriorTextures = useWallSurfaceMaterial(
    0.5,
    0.5,
    exteriorFinish,
    exteriorColor,
  );
  const frontInteriorTextures = useWallSurfaceMaterial(
    0.5,
    0.5,
    interiorFinish,
    interiorColor,
  );
  const sideExteriorTextures = useWallSurfaceMaterial(
    HOUSE_DEPTH / 2,
    WALL_HEIGHT / 2,
    exteriorFinish,
    exteriorColor,
  );
  const sideInteriorTextures = useWallSurfaceMaterial(
    HOUSE_DEPTH / 2,
    WALL_HEIGHT / 2,
    interiorFinish,
    interiorColor,
  );
  const backExteriorTextures = useWallSurfaceMaterial(
    (WALL_WIDTH + 2 * WALL_THICKNESS) / 2,
    WALL_HEIGHT / 2,
    exteriorFinish,
    exteriorColor,
  );
  const backInteriorTextures = useWallSurfaceMaterial(
    (WALL_WIDTH + 2 * WALL_THICKNESS) / 2,
    WALL_HEIGHT / 2,
    interiorFinish,
    interiorColor,
  );

  const lowerWindowCenters = useMemo(() => [WINDOW_CENTER_X], []);
  const upperWindowCenters = useMemo(
    () => [WINDOW_CENTER_X, UPPER_WINDOW_CENTER_X],
    [],
  );
  const lowerWindowHoles = useMemo(
    () =>
      lowerWindowCenters.map((centerX) => ({
        centerX,
        bottomY: FLOOR_Y + WINDOW_SILL_HEIGHT,
        width: WINDOW_WIDTH,
        height: WINDOW_HEIGHT,
      })),
    [lowerWindowCenters],
  );
  const upperWindowHoles = useMemo(
    () =>
      upperWindowCenters.map((centerX) => ({
        centerX,
        bottomY: FLOOR_Y + WINDOW_SILL_HEIGHT,
        width: WINDOW_WIDTH,
        height: WINDOW_HEIGHT,
      })),
    [upperWindowCenters],
  );
  const upperFloorOffsetY = WALL_HEIGHT + INTER_FLOOR_SLAB_THICKNESS;
  const foundationTopY = FLOOR_Y - FOUNDATION_TOP_CLEARANCE;
  const foundationCenterY = foundationTopY - FOUNDATION_HEIGHT / 2;
  const foundationWidth = WALL_WIDTH + 2 * WALL_THICKNESS;
  const foundationDepth = HOUSE_DEPTH + WALL_THICKNESS;
  const foundationCenterZ = WALL_CENTER_Z - HOUSE_DEPTH / 2;
  const foundationFrontFaceZ = foundationCenterZ + foundationDepth / 2;
  const interFloorSlabWidth = foundationWidth - INTER_FLOOR_SLAB_INSET * 2;
  const interFloorSlabDepth = foundationDepth - INTER_FLOOR_SLAB_INSET * 2;
  const interFloorSlabCenterY =
    CEILING_Y + INTER_FLOOR_SLAB_THICKNESS / 2;
  const interFloorSlabCenterZ = foundationCenterZ;
  const stepHeight = FOUNDATION_HEIGHT / STEP_COUNT;
  const stepBaseY = foundationTopY - FOUNDATION_HEIGHT;
  const lowerStepDepth = STEP_DEPTH * STEP_COUNT;
  const interiorFloorYs = [
    foundationTopY + INTERIOR_FLOOR_SURFACE_OFFSET,
    interFloorSlabCenterY +
      INTER_FLOOR_SLAB_THICKNESS / 2 +
      INTERIOR_FLOOR_SURFACE_OFFSET,
  ];
  const foundationMaterialProps = useFacadeTextures(
    foundationWidth / 2,
    FOUNDATION_HEIGHT / 2,
    FOUNDATION_COLOR,
  );
  const accentConcreteMaterialProps = useFacadeTextures(
    interFloorSlabWidth / 2,
    INTER_FLOOR_SLAB_THICKNESS / 2,
    DARK_CONCRETE_COLOR,
  );
  const interiorFloorMaterialProps = useInteriorFloorMaterial();
  const baseStairMaterialProps = useFacadeTextures(
    UPPER_STEP_WIDTH / 2,
    FOUNDATION_HEIGHT / 2,
    STAIR_CONCRETE_COLOR,
  );
  const stairMaterialProps = useMemo(
    () => ({
      ...baseStairMaterialProps,
      roughness: 1,
      roughnessMap: undefined,
      metalness: 0,
      envMapIntensity: 0,
      aoMapIntensity: 0.12,
      normalScale: new THREE.Vector2(0.05, 0.05),
    }),
    [baseStairMaterialProps],
  );
  const stairConfigs = useMemo(
    () => [
      {
        key: 'lower-step',
        width: LOWER_STEP_WIDTH,
        height: stepHeight,
        depth: lowerStepDepth,
      },
      {
        key: 'upper-step',
        width: UPPER_STEP_WIDTH,
        height: FOUNDATION_HEIGHT,
        depth: UPPER_STEP_DEPTH,
      },
    ],
    [lowerStepDepth, stepHeight],
  );

  // Roof dimensions (flush with walls)
  const roofWidth = WALL_WIDTH + 2 * WALL_THICKNESS;
  const roofDepth = HOUSE_DEPTH + WALL_THICKNESS;
  const roofY = CEILING_Y + upperFloorOffsetY + ROOF_THICKNESS / 2;
  const roofZ = WALL_CENTER_Z - HOUSE_DEPTH / 2;

  // Fascia: thin dark strip along front edge of roof
  const roofBottomY = roofY - ROOF_THICKNESS / 2;
  const roofFrontFaceZ = roofZ + roofDepth / 2;
  const fasciaY = roofBottomY + FASCIA_HEIGHT / 2;
  const fasciaZ = roofFrontFaceZ - FASCIA_DEPTH / 2;

  // Floor
  const floorWidth = WALL_WIDTH;
  const floorDepth = HOUSE_DEPTH;
  const floorZ = FRONT_WALL_BACK_FACE_Z - HOUSE_DEPTH / 2;

  return (
    <group>
      <HouseFloorShell
        elevationY={0}
        frontWallOpeningWidth={doorOpeningWidth}
        frontWallOpeningHeight={doorOpeningHeight}
        windowCentersX={lowerWindowCenters}
        windowHoles={lowerWindowHoles}
        frontExteriorTextureMaps={frontExteriorTextures}
        frontInteriorTextureMaps={frontInteriorTextures}
        sideExteriorTextureMaps={sideExteriorTextures}
        sideInteriorTextureMaps={sideInteriorTextures}
        backExteriorTextureMaps={backExteriorTextures}
        backInteriorTextureMaps={backInteriorTextures}
      />

      <HouseFloorShell
        elevationY={upperFloorOffsetY}
        frontWallOpeningWidth={doorOpeningWidth}
        frontWallOpeningHeight={doorOpeningHeight}
        showFrontDoorOpening={false}
        windowCentersX={upperWindowCenters}
        windowHoles={upperWindowHoles}
        frontExteriorTextureMaps={frontExteriorTextures}
        frontInteriorTextureMaps={frontInteriorTextures}
        sideExteriorTextureMaps={sideExteriorTextures}
        sideInteriorTextureMaps={sideInteriorTextures}
        backExteriorTextureMaps={backExteriorTextures}
        backInteriorTextureMaps={backInteriorTextures}
      />

      <ConcreteBox
        materialProps={foundationMaterialProps}
        position={[0, foundationCenterY, foundationCenterZ]}
        size={[foundationWidth, FOUNDATION_HEIGHT, foundationDepth]}
      />

      <ConcreteBox
        materialProps={accentConcreteMaterialProps}
        position={[0, interFloorSlabCenterY, interFloorSlabCenterZ]}
        size={[
          interFloorSlabWidth,
          INTER_FLOOR_SLAB_THICKNESS,
          interFloorSlabDepth,
        ]}
      />

      {stairConfigs.map((stepConfig) => {
        const { key, width, height, depth } = stepConfig;
        const centerY = stepBaseY + height / 2;
        const centerZ = foundationFrontFaceZ + depth / 2;

        return (
          <ConcreteBox
            key={key}
            materialProps={stairMaterialProps}
            position={[0, centerY, centerZ]}
            size={[width, height, depth]}
          />
        );
      })}

      {/* Flat roof with overhang */}
      <mesh position={[0, roofY, roofZ]} castShadow receiveShadow>
        <boxGeometry args={[roofWidth, ROOF_THICKNESS, roofDepth]} />
        <meshStandardMaterial color={ROOF_COLOR} />
      </mesh>

      {/* Roof edge fascia — thin dark strip along front edge */}
      <mesh position={[0, fasciaY, fasciaZ]}>
        <boxGeometry args={[roofWidth, FASCIA_HEIGHT, FASCIA_DEPTH]} />
        <meshStandardMaterial color={FASCIA_COLOR} />
      </mesh>

      {interiorFloorYs.map((y) => (
        <mesh
          key={y}
          position={[0, y, floorZ]}
          rotation={[-Math.PI / 2, 0, 0]}
          receiveShadow
        >
          <planeGeometry args={[floorWidth, floorDepth]} />
          <meshStandardMaterial
            {...interiorFloorMaterialProps}
            side={THREE.DoubleSide}
          />
        </mesh>
      ))}
    </group>
  );
};

